/** A close-delimited, delayed SSE upstream; generated bytes only, no model or image. */
import { createServer } from 'node:net'
import type { Socket, AddressInfo } from 'node:net'

export async function delayedSseServer(stall = false) {
  let markClosed!: () => void
  const closed = new Promise<void>((resolve) => {
    markClosed = resolve
  })
  const sockets = new Set<Socket>()
  const timers = new Set<ReturnType<typeof setInterval>>()
  const frames = Array.from({ length: 20 }, (_, i) => `data: {"i":${i},"text":"${'x'.repeat(128)}"}\n\n`)
  const first = 'data: {"role":"assistant"}\n\n'
  const expected = first + frames.join('') + 'data: [DONE]\n\n'
  const server = createServer((socket) => {
    sockets.add(socket)
    socket.on('error', () => {})
    socket.once('close', () => {
      sockets.delete(socket)
      markClosed()
    })
    let input = Buffer.alloc(0)
    let started = false
    socket.on('data', (chunk) => {
      if (started) return
      input = Buffer.concat([input, chunk])
      const separator = input.indexOf('\r\n\r\n')
      if (separator < 0) return
      const head = input.subarray(0, separator).toString()
      const length = Number(/content-length: (\d+)/i.exec(head)?.[1] ?? 0)
      if (input.length < separator + 4 + length) return
      started = true
      input = Buffer.alloc(0)
      socket.write('HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nConnection: close\r\n\r\n')
      socket.write(first)
      if (stall) return
      let index = 0
      const timer = setInterval(() => {
        if (socket.destroyed) {
          clearInterval(timer)
          timers.delete(timer)
          return
        }
        socket.write(frames[index++] as string)
        if (index === frames.length) {
          clearInterval(timer)
          timers.delete(timer)
          socket.end('data: [DONE]\n\n')
        }
      }, 35)
      timers.add(timer)
    })
  })
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve))
  return {
    url: `http://127.0.0.1:${(server.address() as AddressInfo).port}/chat/completions`,
    expected,
    closed,
    async close() {
      for (const timer of timers) clearInterval(timer)
      for (const socket of sockets) socket.destroy()
      await new Promise<void>((resolve) => server.close(() => resolve()))
    },
  }
}
